<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/session.run.php';
require_once __DIR__ . '/../includes/conn.dbh.php';
if (empty($_SESSION['user_info']['id'])) { header('Location: /cnrbyte/signup_login/signup_login.pge.php'); exit; }
$clientId=(int)$_SESSION['user_info']['id']; $vendorId=(int)($_SESSION['vendor_info']['id']??0);
if($vendorId<1){header('Location: /cnrbyte/vendors/select.pge.php');exit;}
$stmt=$conn->prepare('SELECT * FROM vendors WHERE id=? AND (client_id=? OR user_id=?) LIMIT 1');$stmt->bind_param('iii',$vendorId,$clientId,$clientId);$stmt->execute();$vendor=$stmt->get_result()->fetch_assoc();$stmt->close();
if(!$vendor){unset($_SESSION['vendor_info']);http_response_code(403);exit('You do not have access to this vendor workspace.');}
$_SESSION['vendor_info']['reg_name']=(string)$vendor['reg_name']; $_SESSION['current_dashboard']='vendors_dashboard'; $_SESSION['selected_pge']='dashboard_pge';
$stmt=$conn->prepare('SELECT * FROM profiles WHERE vendor_id=? ORDER BY id DESC LIMIT 1');$stmt->bind_param('i',$vendorId);$stmt->execute();$profile=$stmt->get_result()->fetch_assoc()?:[];$stmt->close();
function vendor_dash_h($v): string { return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
$counts=[]; foreach(['Branches'=>['branches','vendor_id'],'Shifts'=>['shifts','vendor_id'],'Staff'=>['staff','vendor_id'],'Products'=>['products','vendor_id'],'Orders'=>['marketplace_orders','vendor_id']] as $label=>[$table,$column]) { try{$stmt=$conn->prepare("SELECT COUNT(*) AS total FROM {$table} WHERE {$column}=?");$stmt->bind_param('i',$vendorId);$stmt->execute();$counts[$label]=(int)($stmt->get_result()->fetch_assoc()['total']??0);$stmt->close();}catch(Throwable $e){$counts[$label]=null;} }
$unread=0; try{$type='vendor';$stmt=$conn->prepare('SELECT COUNT(*) AS total FROM cnrbyte_messages WHERE recipient_type=? AND recipient_id=? AND is_read=0');$stmt->bind_param('si',$type,$vendorId);$stmt->execute();$unread=(int)($stmt->get_result()->fetch_assoc()['total']??0);$stmt->close();}catch(Throwable $e){}
?>
