<h3>Physical address</h3><p><?=vendor_dash_h($profile['str_address']??'')?><?=!empty($profile['phy_suburb'])?', '.vendor_dash_h($profile['phy_suburb']):''?><?=!empty($profile['phy_town'])?', '.vendor_dash_h($profile['phy_town']):''?><?=!empty($profile['phy_province'])?', '.vendor_dash_h($profile['phy_province']):''?><?=!empty($profile['phy_postal_code'])?' '.vendor_dash_h($profile['phy_postal_code']):''?></p>
<p><a class="cnr-button" href="/cnrbyte/vendors/profile.pge.php">Edit business profile</a></p></section>
<section class="cnr-form-card"><h2>Public profile</h2><?php if(!empty($profile['about_para_text'])): ?><p><?=nl2br(vendor_dash_h($profile['about_para_text']))?></p><?php if(!empty($profile['about_img']) && basename((string)$profile['about_img'])===(string)$profile['about_img'] && is_file(__DIR__ . '/../uploads/vendors/profile/' . $profile['about_img'])): ?><p><img src="/cnrbyte/uploads/vendors/profile/<?=vendor_dash_h($profile['about_img'])?>" alt="About the business" style="max-width:320px;max-height:220px;object-fit:cover"></p><?php endif; ?><?php else: ?><p class="cnr-empty-state">Add an About description so customers can learn about your business.</p><?php endif; ?><?php foreach(['vision'=>'Vision','mission'=>'Mission','values'=>'Values'] as $key=>$label): $col=$key.'_para_text'; $imgCol=$key.'_img'; if(!empty($profile[$col]) || !empty($profile[$imgCol])): ?><h3><?=vendor_dash_h($label)?></h3><?php if(!empty($profile[$col])): ?><p><?=nl2br(vendor_dash_h($profile[$col]))?></p><?php endif; ?><?php if(!empty($profile[$imgCol]) && basename((string)$profile[$imgCol])===(string)$profile[$imgCol] && is_file(__DIR__ . '/../uploads/vendors/profile/' . $profile[$imgCol])): ?><p><img src="/cnrbyte/uploads/vendors/profile/<?=vendor_dash_h($profile[$imgCol])?>" alt="<?=vendor_dash_h($label)?>" style="max-width:320px;max-height:220px;object-fit:cover"></p><?php endif; ?><?php endif; endforeach; ?><a class="cnr-header-link" href="/cnrbyte/vendors/profile.pge.php">Update public profile details</a></section>
